classdef filterUtilsTest < matlab.unittest.TestCase
%FILTERUTILSTEST  Unit tests for sfreqz, sinvfreqz and sstmcb.
%
%   These are the base-MATLAB replacements for the Signal Processing Toolbox
%   freqz / invfreqz / stmcb, promoted to standalone functions. The tests
%   check them directly (independently of psd2arma).
%
%   Run with:  results = runtests('filterUtilsTest')
%
%   ------------------------------------------------------------------
%   Toolbox : sigtools (tests)
%   Author  : Generated by Claude Opus 4.8 (Anthropic)
%   Date    : 2026-07-15  (build time-of-day not available in this environment)
%   ------------------------------------------------------------------

    methods (Test)

    % -------------------------------------------------------- sfreqz
    function sfreqzMatchesManualEval(tc)
        b = [1 -0.5 0.2]; a = [1 -1.2 0.6];
        w = linspace(0, pi, 200)';
        H = timeSeriesPreparation.spectral.sfreqz(b, a, w);
        z = exp(-1i*w);
        Bref = b(1) + b(2)*z + b(3)*z.^2;
        Aref = a(1) + a(2)*z + a(3)*z.^2;
        tc.verifyEqual(H, Bref./Aref, 'RelTol', 1e-12);
    end

    function sfreqzHzConversion(tc)
        b = 1; a = [1 -0.7]; Fs = 100;
        f = (0:0.5:Fs/2)';
        [H1, w] = timeSeriesPreparation.spectral.sfreqz(b, a, f, Fs);
        H2 = timeSeriesPreparation.spectral.sfreqz(b, a, 2*pi*f/Fs);
        tc.verifyEqual(H1, H2, 'RelTol', 1e-12);
        tc.verifyEqual(w, 2*pi*f/Fs, 'RelTol', 1e-12);
    end

    function sfreqzDCValue(tc)
        % At w=0 (z=1), H = sum(b)/sum(a).
        b = [1 2 3]; a = [1 -0.5 0.25];
        H = timeSeriesPreparation.spectral.sfreqz(b, a, 0);
        tc.verifyEqual(H, sum(b)/sum(a), 'RelTol', 1e-12);
    end

    % ------------------------------------------------------ sinvfreqz
    function sinvfreqzRecoversKnownARMA(tc)
        b = [1 -0.5 0.2]; a = [1 -1.2 0.6];
        w = linspace(0, pi, 400)';
        Hd = timeSeriesPreparation.spectral.sfreqz(b, a, w);
        [bh, ah] = timeSeriesPreparation.spectral.sinvfreqz(Hd, w, 2, 2, 40);
        Hf = timeSeriesPreparation.spectral.sfreqz(bh, ah, w);
        tc.verifyLessThan(max(abs(Hf - Hd)), 1e-9);
        % PSD ratio essentially unity
        tc.verifyLessThan(max(abs(abs(Hf).^2 ./ abs(Hd).^2 - 1)), 1e-9);
    end

    function sinvfreqzFitsSmoothTarget(tc)
        % Non-rational low-pass magnitude: minimum-phase target, low RMS.
        N = 1024; Fs = 500; fg = linspace(0, Fs/2, N+1)';
        S = 1 ./ (1 + (fg/5).^2).^2;
        mag = sqrt(S*Fs/2);
        magFull = [mag; flipud(mag(2:end-1))];
        magFull = max(magFull, max(magFull)*1e-9);
        cep = real(ifft(log(magFull)));
        win = zeros(2*N,1); win(1)=1; win(2:N)=2; win(N+1)=1;
        Hmin = exp(fft(cep.*win)); Hmin = Hmin(1:N+1);
        w = pi*fg/(Fs/2);
        [b, a] = timeSeriesPreparation.spectral.sinvfreqz(Hmin, w, 4, 4, 40);
        Hf = timeSeriesPreparation.spectral.sfreqz(b, a, w);
        psd = (2/Fs)*abs(Hf).^2;
        errDb = 10*log10(max(psd,1e-30)./max(S,1e-30));
        tc.verifyLessThan(sqrt(mean(errDb.^2)), 0.5);
    end

    % -------------------------------------------------------- sstmcb
    function sstmcbRecoversKnownARMA(tc)
        b = [1 -0.5 0.2]; a = [1 -1.2 0.6];
        h = filter(b, a, [1; zeros(80,1)]);
        [bh, ah] = timeSeriesPreparation.spectral.sstmcb(h, 2, 2, 12);
        tc.verifyEqual(bh, b, 'AbsTol', 1e-6);
        tc.verifyEqual(ah, a, 'AbsTol', 1e-6);
    end

    function sstmcbImpulseReproduced(tc)
        b = [1 0.3]; a = [1 -0.9 0.2];
        h = filter(b, a, [1; zeros(120,1)]);
        [bh, ah] = timeSeriesPreparation.spectral.sstmcb(h, 1, 2, 15);
        hh = filter(bh, ah, [1; zeros(120,1)]);
        tc.verifyLessThan(max(abs(hh - h)), 1e-6);
    end

    end
end
